    private String readQueue(Intent intent)throws Exception{String file=intent.getStringExtra("queueFile");if(file==null)return intent.getStringExtra("queue");if(!file.matches("mygo-queue-[A-Za-z0-9-]+\\.json"))throw new IOException("无效的播放队列文件");File path=new File(getCacheDir(),file);try{if(path.length()>8*1024*1024)throw new IOException("播放队列超过大小限制");return PluginIdentity.read(path);}finally{path.delete();}}
    static void startQueue(Context context,JSONArray queue,int index,int position,int volume,boolean shuffle,boolean repeat,String quality)throws IOException{
        byte[] data=queue.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);if(data.length>8*1024*1024)throw new IOException("播放队列超过 8 MB");Intent intent=new Intent(context,PlaybackService.class).setAction(ACTION_QUEUE).putExtra("index",index).putExtra("position",position).putExtra("volume",volume).putExtra("shuffle",shuffle).putExtra("repeat",repeat).putExtra("quality",quality);File file=null;
        try{if(data.length>200000){file=File.createTempFile("mygo-queue-",".json",context.getCacheDir());try(FileOutputStream output=new FileOutputStream(file)){output.write(data);}intent.putExtra("queueFile",file.getName());}else intent.putExtra("queue",new String(data,java.nio.charset.StandardCharsets.UTF_8));if(Build.VERSION.SDK_INT>=26)context.startForegroundService(intent);else context.startService(intent);}catch(Exception error){if(file!=null)file.delete();if(error instanceof IOException)throw (IOException)error;throw new IOException(error);}
    }

